function bar(items,unit='',shares=false){let max=Math.max(...items.map(a=>a[1])),total=items.reduce((s,a)=>s+a[1],0);return `<div class="bars">`+items.map((a,i)=>`<div class="barrow"><span class="bar-label">${esc(a[0])}</span><span class="n">${nf(a[1],unit==='مليون'?2:1)}${shares?' <small>· '+nf(a[1]/total*100)+'%</small>':''}</span><div class="track"><div class="fill" style="width:${max?a[1]/max*100:0}%"></div></div></div>`).join('')+'</div>'}
