function update(){render();enhance(); document.querySelectorAll('#nav button').forEach((b,i)=>{b.classList.toggle('active',i===page);b.setAttribute('aria-selected',i===page?'true':'false');b.tabIndex=i===page?0:-1}); document.querySelectorAll('.page').forEach((p,i)=>{p.classList.toggle('active',i===page); p.hidden=i!==page}); $('#reportStatus').textContent=`${document.querySelector('#nav .active .nav-title').textContent}، ${$('#year').value}`; }
function activate(index,focus=false){page=index;update(); if(focus)document.querySelector('#nav .active').focus(); window.scrollTo({top:0,behavior:'instant'});}
$('#year').onchange=update;$('#type').onchange=update;
$('#reset').onclick=()=>{$('#year').value='2025';$('#type').value='all';update()};
document.querySelectorAll('#nav button').forEach(b=>{b.onclick=()=>activate(+b.dataset.page);b.onkeydown=e=>{let next=page;if(e.key==='ArrowDown'||e.key==='ArrowLeft')next=(page+1)%6;else if(e.key==='ArrowUp'||e.key==='ArrowRight')next=(page+5)%6;else if(e.key==='Home')next=0;else if(e.key==='End')next=5;else return;e.preventDefault();activate(next,true)}});
$('#print').onclick=()=>window.print();
let printDetails=[], printRows=[];
window.addEventListener('beforeprint',()=>{printRows=[...document.querySelectorAll('tbody tr')].map(el=>[el,el.hidden]);printRows.forEach(([el])=>el.hidden=false);printDetails=[...document.querySelectorAll('details')].map(el=>[el,el.open]);printDetails.forEach(([el])=>el.open=true);document.querySelectorAll('.page').forEach(el=>el.hidden=false)});
window.addEventListener('afterprint',()=>{printRows.forEach(([el,hidden])=>el.hidden=hidden);printDetails.forEach(([el,open])=>el.open=open);document.querySelectorAll('.page').forEach((el,i)=>el.hidden=i!==page)});
